css:
.bauhaus-container {
  --ui-bg: #f2f0e9;
  --ui-text: #1a1a1a;
  --ui-accent: #e63946;
  --ui-border: #1a1a1a;

  background: var(--ui-bg);
  padding: 40px;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 250px;
  font-family: "Inter", "Helvetica", sans-serif;
  color: var(--ui-text);
}

.bauhaus-group {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 20px;
  border-left: 8px solid var(--ui-border);
  padding-left: 24px;
}

.bauhaus-header {
  display: flex;
  align-items: baseline;
  gap: 12px;
  margin-bottom: 10px;
}

.bauhaus-header .num {
  font-size: 1.2rem;
  font-weight: 900;
  text-decoration: underline;
  text-underline-offset: 4px;
}

.bauhaus-header .title {
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 0.2em;
  font-weight: 700;
}

.radio-options {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.radio-item {
  display: flex;
  align-items: center;
  cursor: pointer;
  position: relative;
  transition: transform 0.2s ease;
}

.radio-item:hover {
  transform: translateX(8px);
}

.radio-item input {
  position: absolute;
  opacity: 0;
  width: 0;
  height: 0;
}

.selector-box {
  width: 32px;
  height: 32px;
  border: 3px solid var(--ui-border);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-right: 16px;
  position: relative;
  background: transparent;
  transition: all 0.3s cubic-bezier(0.19, 1, 0.22, 1);
}

.shape {
  width: 0;
  height: 0;
  transition: all 0.4s cubic-bezier(0.68, -0.55, 0.265, 1.55);
  opacity: 0;
}

.shape-circle {
  border-radius: 50%;
  background: var(--ui-accent);
}

.shape-square {
  background: var(--bauhaus-blue);
}

.shape-triangle {
  width: 0;
  height: 0;
  border-left: 10px solid transparent;
  border-right: 10px solid transparent;
  border-bottom: 20px solid var(--bauhaus-yellow);
  background: transparent !important;
}

/* Checked States */
.radio-item input:checked + .selector-box {
  background: var(--ui-border);
}

.radio-item input:checked + .selector-box .shape {
  opacity: 1;
  width: 18px;
  height: 18px;
}

.radio-item input:checked + .selector-box .shape-triangle {
  width: 0;
  height: 0;
  transform: translateY(-2px);
}

.label-text {
  font-size: 1.4rem;
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: -0.02em;
  transition: color 0.3s ease;
}

.radio-item input:checked ~ .label-text {
  color: var(--ui-accent);
}

/* Bauhaus Decorative Elements */
.bauhaus-decoration {
  position: absolute;
  top: -20px;
  right: -60px;
  width: 40px;
  height: 40px;
  pointer-events: none;
}

.line-v {
  position: absolute;
  width: 3px;
  height: 100px;
  background: var(--bauhaus-yellow);
  top: 0;
  right: 10px;
}

.line-h {
  position: absolute;
  width: 60px;
  height: 12px;
  background: var(--bauhaus-blue);
  bottom: -40px;
  right: -20px;
  z-index: -1;
}
